/**
 * Parse the arcade script and collect the names of direct function calls. Throws an error if the script cannot be parsed.
 *
 * @param script - the arcade script to analyze.
 * @returns the ids (lowercase name) of all direct function calls referenced in the script.
 * @internal
 * @example
 * getCalledFunctionNames(`\
 *   // var fs = FeatureSetByName(...);
 *   var fs = FeatureSetByPortalItem(...);
 *   return Count(fs);
 * `);
 * // returns `{"featuresetbyportalitem", "count"}`
 * @internal
 */
export function getCalledFunctionNames(script: string): Set<Lowercase<string>>;